    (hX : MemLp X 2 μ) (hY : MemLp Y 2 μ) (x y : WithLp 2 (ℝ × ℝ)) :
    covarianceBilin (μ.map (fun ω ↦ toLp 2 (X ω, Y ω))) x y =
      x.fst * y.fst * Var[X; μ] + (x.fst * y.snd + x.snd * y.fst) * cov[X, Y; μ] +
      x.snd * y.snd * Var[Y; μ]

